// opening-return-navigation.js
var RETURN_MARKER = "<!--sta-opening-return-->";
function stripOpeningReturnMarker(text) {
  let value = String(text ?? "");
  while (value.endsWith(RETURN_MARKER)) value = value.slice(0, -RETURN_MARKER.length);
  return value;
}
function markOpeningReturn(text) {
  const value = stripOpeningReturnMarker(text);
  return value.trim() && value.trim() !== "\u3010\u4E3B\u9875\u3011" ? value + RETURN_MARKER : value;
}
function homeSwipeIndex(swipes) {
  const matches = (Array.isArray(swipes) ? swipes : []).flatMap((text, index) => String(text).trim() === "\u3010\u4E3B\u9875\u3011" ? [index] : []);
  return matches.length === 1 ? matches[0] : -1;
}
async function returnToOpeningHome(ctx, messageElement, helper) {
  const message = ctx?.chat?.[0];
  const target = homeSwipeIndex(message?.swipes);
  if (target < 0) throw new Error("\u672A\u627E\u5230\u552F\u4E00\u4E3B\u9875\uFF0C\u8BF7\u91CD\u65B0\u5E94\u7528\u5F00\u573A\u767D\u4E3B\u9875");
  if (helper?.setChatMessages) {
    await helper.setChatMessages([{ message_id: 0, swipe_id: target }], { refresh: "affected" });
    return;
  }
  const current = Number(message.swipe_id || 0);
  const direction = target > current ? "right" : "left";
  if (!ctx?.swipe?.[direction]) throw new Error("\u5F53\u524D\u73AF\u5883\u6CA1\u6709\u5F00\u573A\u767D\u5207\u6362\u63A5\u53E3");
  for (let i = 0; i < Math.abs(target - current); i++) {
    await ctx.swipe[direction].call(messageElement, null, { source: "jiuyi-opening-home", message });
  }
}
function mountOpeningReturnNavigation(getContext, enabled, doc = document) {
  let pending = 0;
  const id = "status-atelier-return-home";
  function render() {
    pending = 0;
    const ctx = getContext();
    const target = homeSwipeIndex(ctx?.chat?.[0]?.swipes);
    const message = doc.querySelector('#chat .mes[mesid="0"]');
    const existing = doc.getElementById(id);
    if (!enabled() || !message || target < 0 || Number(ctx.chat[0].swipe_id || 0) === target) {
      existing?.remove();
      return;
    }
    if (existing && message.contains(existing)) return;
    existing?.remove();
    const button = doc.createElement("button");
    button.id = id;
    button.className = "menu_button";
    button.textContent = "\u2190 \u8FD4\u56DE\u4F5C\u54C1\u76EE\u5F55";
    button.style.cssText = "display:block;margin:10px auto;";
    button.addEventListener("click", async () => {
      button.disabled = true;
      try {
        await returnToOpeningHome(getContext(), message, globalThis.TavernHelper);
      } catch (error) {
        button.textContent = error.message;
      } finally {
        button.disabled = false;
      }
    });
    (message.querySelector(".mes_block") || message).append(button);
  }
  const observer = new MutationObserver(() => {
    if (!pending) pending = requestAnimationFrame(render);
  });
  observer.observe(doc.querySelector("#chat") || doc.body, { childList: true, subtree: true });
  render();
  return () => {
    observer.disconnect();
    cancelAnimationFrame(pending);
    doc.getElementById(id)?.remove();
  };
}
async function portableOpeningReturn() {
  const button = document.getElementById("sta-opening-return");
  const note2 = document.getElementById("sta-opening-return-note");
  function syncFrame() {
    try {
      const frame = typeof window === "undefined" ? null : window.frameElement;
      if (!frame) return;
      const visible = !button.hidden || !note2.hidden;
      frame.hidden = !visible;
      frame.style.display = visible ? "block" : "none";
      frame.style.height = visible ? `${Math.ceil(document.body.scrollHeight)}px` : "0px";
    } catch {
    }
  }
  syncFrame();
  try {
    if (typeof getCurrentMessageId !== "function" || getCurrentMessageId() !== 0) return;
    if (typeof getChatMessages !== "function" || typeof setChatMessages !== "function") {
      note2.hidden = false;
      note2.textContent = "\u8FD4\u56DE\u76EE\u5F55\u9700\u8981\u542F\u7528\u9152\u9986\u52A9\u624B\u7684\u524D\u7AEF\u6E32\u67D3\u3002";
      return;
    }
    async function locate() {
      const rows = await getChatMessages("0", { include_swipes: true });
      const row = rows[0];
      const matches = (row?.swipes || []).flatMap((text, i) => String(text).trim() === "\u3010\u4E3B\u9875\u3011" ? [i] : []);
      return { row, target: matches.length === 1 ? matches[0] : -1 };
    }
    const initial = await locate();
    if (initial.target < 0 || initial.row.swipe_id === initial.target) return;
    button.hidden = false;
    button.addEventListener("click", async () => {
      button.disabled = true;
      try {
        const latest = await locate();
        if (latest.target < 0) throw new Error("\u672A\u627E\u5230\u552F\u4E00\u4F5C\u54C1\u76EE\u5F55\uFF0C\u8BF7\u68C0\u67E5\u8FD9\u5F20\u5361\u7684\u5F00\u573A\u767D\u3002");
        await setChatMessages([{ message_id: 0, swipe_id: latest.target }], { refresh: "affected" });
      } catch (error) {
        note2.hidden = false;
        note2.textContent = error.message || "\u8FD4\u56DE\u5931\u8D25\uFF0C\u8BF7\u91CD\u8BD5";
      } finally {
        button.disabled = false;
        syncFrame();
      }
    });
  } catch (error) {
    note2.hidden = false;
    note2.textContent = error.message || "\u8BFB\u53D6\u5F00\u573A\u767D\u5931\u8D25";
  } finally {
    syncFrame();
  }
}
function buildOpeningReturnRegex() {
  return {
    id: "jiuyi-opening-return-portable-v1",
    scriptName: "\u4E5D\u4E00 \xB7 \u5F00\u573A\u767D\u8FD4\u56DE\u4F5C\u54C1\u76EE\u5F55",
    disabled: false,
    runOnEdit: true,
    findRegex: "/<!--sta-opening-return-->$/",
    trimStrings: [],
    // Replace only the owned suffix; ordinary conversation is never matched.
    replaceString: '\n\n```html\n<!DOCTYPE html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>html,body{margin:0;background:transparent;scrollbar-width:none}*::-webkit-scrollbar{display:none}button{display:block;margin:8px auto;padding:7px 16px;border:1px solid #9c8970;border-radius:4px;background:#f3eadb;color:#594638;font:14px/1.5 serif;cursor:pointer}[hidden]{display:none!important}p{margin:4px;font:13px/1.5 serif;color:#a54b39}</style></head><body><button id="sta-opening-return" type="button" hidden>\u2190 \u8FD4\u56DE\u4F5C\u54C1\u76EE\u5F55</button><p id="sta-opening-return-note" role="status" hidden></p><script>(' + portableOpeningReturn.toString() + ")();<\/script></body></html>\n```\n",
    placement: [2],
    substituteRegex: 0,
    minDepth: null,
    maxDepth: null,
    markdownOnly: true,
    promptOnly: false
  };
}

