  const fonts = { serif: '"Noto Serif SC",SimSun,serif', sans: '"Microsoft YaHei","PingFang SC",sans-serif', kai: "KaiTi,STKaiti,serif", mono: "monospace", fangsong: "FangSong,serif", rounded: "YouYuan,sans-serif", clerical: "LiSu,serif" };
  const runtime = navigationScript.replace("script.previousElementSibling.previousElementSibling", "document.querySelector('.zoh-root')");
