    const position = root.querySelector("[data-person-position]");
    if (position) position.textContent = `${selected + 1} / ${pages.length} \xB7 ${page.label}`;
    const avatar = root.querySelector("[data-st-avatar]");
    let url = config.avatarSource === "none" ? "" : config.ensembleAvatarUrls[selected] || (selected === 0 ? config.avatarUrl : "");
    try {
      const context2 = window.parent.SillyTavern?.getContext?.();
      const character = context2?.characters?.find((item) => item.name === page.label);
      if (config.avatarSource === "character" && !url && character?.avatar) url = context2.getThumbnailUrl ? context2.getThumbnailUrl("avatar", character.avatar) : "/thumbnail?type=avatar&file=" + encodeURIComponent(character.avatar);
    } catch {
    }
    if (url) avatar.src = url;
    else avatar.removeAttribute("src");
    avatar.alt = page.label;
    avatar.nextElementSibling.textContent = page.label.slice(0, 1);
