function isStatusBeauty32To41(structure) {
  return STATUS_BEAUTY_32_41_IDS.includes(structure);
}
function buildStatusBeauty32To41Replacement(rule) {
  return `\`\`\`html
${buildDocument(rule, "$1")}
\`\`\``;
}
function buildStatusBeauty32To41Preview(rule, rawValues = []) {
  const sanitize = (value) => String(value || "\u2014").replace(/[|[\]<>]/g, " ");
  const preset2 = STATUS_BEAUTY_32_41_PRESETS.find((item) => item.id === rule.structure);
  if (preset2?.dynamicRoster && Array.isArray(rawValues[0])) {
    return buildDocument(rule, rawValues.map((values, index) => `[View${index + 1}|${values.map(sanitize).join("|")}]`).join("\n"));
  }
  if (preset2?.contract === "ensemble" || Array.isArray(rawValues[0])) {
    const nested = Array.isArray(rawValues[0]) ? rawValues : (rule.pages || []).map((_, index) => rawValues.slice(index * preset2.fields.length, (index + 1) * preset2.fields.length));
    const source = (rule.pages || []).map((page, index) => `[${page.id}|${(nested[index] || []).map(sanitize).join("|")}]`).join("\n");
    return buildDocument(rule, source);
  }
  const pageId = rule.pages?.[0]?.id || "View1";
  return buildDocument(rule, `[${pageId}|${rawValues.map(sanitize).join("|")}]`);
}

