function createStatusInstallInstance(script, entry, token) {
  const key = String(token).replace(/[^a-zA-Z0-9]/g, "");
  if (!key) throw new Error("\u72B6\u6001\u680F\u5B89\u88C5\u6807\u8BC6\u4E3A\u7A7A");
  const match = String(script.findRegex || "").match(/^\/?<([^>]+)>/);
  if (!match) throw new Error("\u65E0\u6CD5\u8BC6\u522B\u72B6\u6001\u680F\u8F93\u51FA\u6807\u7B7E\uFF0C\u5DF2\u505C\u6B62\u5B89\u88C5\u4EE5\u4FDD\u62A4\u5DF2\u6709\u6B63\u5219");
  const pattern = match[1];
  const tags = pattern.startsWith("(?:") ? pattern.slice(3, -1).split("|") : [pattern];
  if (tags.some((tag2) => !/^[\w-]+$/.test(tag2))) throw new Error("\u72B6\u6001\u680F\u8F93\u51FA\u6807\u7B7E\u65E0\u6CD5\u5B89\u5168\u533A\u5206\uFF0C\u5DF2\u505C\u6B62\u5B89\u88C5");
  const tag = `sta_${key}`;
  const findRegex = script.findRegex.replaceAll(`<${pattern}>`, `<${tag}>`).replaceAll(`<\\/${pattern}>`, `<\\/${tag}>`).replaceAll(`</${pattern}>`, `</${tag}>`);
  let content = String(entry.content || "");
  for (const oldTag of tags) content = content.replaceAll(`<${oldTag}>`, `<${tag}>`).replaceAll(`</${oldTag}>`, `</${tag}>`);
  if (!content.includes(`<${tag}>`)) throw new Error("\u4E16\u754C\u4E66\u4E0E\u6B63\u5219\u6807\u7B7E\u4E0D\u4E00\u81F4\uFF0C\u5DF2\u505C\u6B62\u5B89\u88C5");
  return {
    script: { ...script, id: `sta-instance-${key}`, statusAtelierInstance: key, scriptName: script.scriptName, findRegex },
    entry: { ...entry, automationId: `jiuyi-wb-instance-${key}`, comment: entry.comment, content }
  };
}

